use std::os::unix::fs::MetadataExt;
use std::{fs,path::{Path,PathBuf}};
use serde_json::{json,Value};
type R<T> = Result<T,Box<dyn std::error::Error>>;
fn registry(root:&Path)->PathBuf{root.join(".atlas-external-workspaces.json")}
pub fn load(root:&Path)->R<Vec<Value>> {let path=registry(root);if path.is_symlink(){return Err("invalid external registry".into())}if !path.exists(){return Ok(vec![])}Ok(serde_json::from_slice(&fs::read(path)?)?)}
fn save(root:&Path,entries:&[Value])->R<()> {let path=registry(root);if path.is_symlink(){return Err("invalid external registry".into())}let tmp=root.join(format!(".atlas-registry-{}.tmp",uuid::Uuid::new_v4().simple()));let result=(||->R<()>{use std::io::Write;let mut f=fs::OpenOptions::new().write(true).create_new(true).open(&tmp)?;f.write_all(&serde_json::to_vec(entries)?)?;f.sync_all()?;fs::rename(&tmp,&path)?;fs::File::open(root)?.sync_all()?;Ok(())})();if result.is_err(){let _=fs::remove_file(tmp);}result}
pub fn resolve(root:&Path,default:&Path,id:&str)->R<PathBuf>{if id=="default"{return Ok(default.to_owned())}if id.len()!=32||!id.chars().all(|c|c.is_ascii_hexdigit()){return Err("invalid workspace id".into())}for e in load(root)?{if e["id"]==id{let path=PathBuf::from(e["path"].as_str().ok_or("invalid path")?);let marker=path.join(".atlas-workspace-id");let meta=fs::metadata(&path)?;if path.is_symlink()||marker.is_symlink()||fs::read_to_string(&marker).ok().as_deref()!=e["identity"].as_str()||Some(meta.dev())!=e["device"].as_u64()||Some(meta.ino())!=e["inode"].as_u64(){return Err("external workspace unavailable; select it again".into())}return Ok(path)}}Ok(root.join(id))}
pub fn attach(root:&Path,default:&Path,path:&Path)->R<Value>{if !path.is_absolute()||path.is_symlink(){return Err("invalid workspace path".into())}let path=path.canonicalize()?;if path.starts_with(root.canonicalize()?)||default.canonicalize().ok().as_ref()==Some(&path){return Err("workspace already managed by Atlas".into())}if !super::valid_workspace(&path){return Err("invalid workspace".into())}let mut entries=load(root)?;if let Some(index)=entries.iter().position(|entry|entry["path"].as_str()==path.to_str()){let marker=path.join(".atlas-workspace-id");if marker.is_symlink()||fs::read_to_string(marker).ok().as_deref()!=entries[index]["identity"].as_str(){return Err("different workspace at registered path; detach first".into())}let meta=fs::metadata(&path)?;entries[index]["device"]=json!(meta.dev());entries[index]["inode"]=json!(meta.ino());let entry=entries[index].clone();save(root,&entries)?;return Ok(entry)}
 let name=[".workspace.json",".atlas-workspace.json"].iter().find_map(|n|fs::read(path.join(n)).ok().and_then(|s|serde_json::from_slice::<Value>(&s).ok()).and_then(|v|v["name"].as_str().map(str::to_owned))).or_else(||path.file_name().map(|x|x.to_string_lossy().to_string())).ok_or("missing name")?;
 let marker=path.join(".atlas-workspace-id");if marker.is_symlink(){return Err("invalid workspace identity".into())}if !marker.exists(){use std::io::Write;let mut f=fs::OpenOptions::new().write(true).create_new(true).open(&marker)?;f.write_all(uuid::Uuid::new_v4().simple().to_string().as_bytes())?;f.sync_all()?;}let identity=fs::read_to_string(&marker)?;if identity.len()!=32||!identity.chars().all(|c|c.is_ascii_hexdigit()){return Err("invalid workspace identity".into())}
 let meta=fs::metadata(&path)?;let item=json!({"id":uuid::Uuid::new_v4().simple().to_string(),"name":name,"identity":identity,"device":meta.dev(),"inode":meta.ino(),"path":path.to_str().ok_or("invalid path")?});entries.push(item.clone());save(root,&entries)?;Ok(item)}
pub fn detach(root:&Path,id:&str)->R<bool>{let mut entries=load(root)?;let old=entries.len();entries.retain(|e|e["id"]!=id);if entries.len()!=old{save(root,&entries)?;Ok(true)}else{Ok(false)}}

pub fn rename(root:&Path,id:&str,name:&str)->R<()> {let mut entries=load(root)?;if let Some(entry)=entries.iter_mut().find(|e|e["id"]==id){entry["name"]=json!(name);save(root,&entries)?;}Ok(())}
